-- El juego de caracteres se fija SIEMPRE: el cliente `mysql` lo toma del entorno y en un
-- contenedor sin locale eso es latin1, que convierte cada tilde en mojibake sin dar error.
SET NAMES utf8mb4;
-- Fotos de puntos de interés (poi-images.js)
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Barrancos_de_Gebas.jpg?width=1280', source = 'Decreto n.º 13/1995, de 31 de marzo, por el que se aprueba el Plan de Ordenación de los Recursos Naturales de Sierra Espuña (incluido Barrancos de Gebas) y se declara como Paisaje Protegido los Barrancos de Gebas (BORM n.º 85, de 11 de abril de 1995), Memoria Descriptiva §1.3.1.2: el área catalogada como Lugar de Interés Geológico por la Agencia Regional para el Medio Ambiente y la Naturaleza es la «Cabecera de la Rambla de Algeciras», también denominada Barrancos de Gebas, «considerada de interés por su contenido geomorfológico y su utilización didáctica, con una categoría de importancia internacional»; el mismo apartado sitúa en Gebas el máximo desarrollo de los «bad lands». PDF consultado de primera mano el 2026-08-22. Coordenada de OpenStreetMap (node/9156604473, tourism=viewpoint, ODbL). NOTA: este LIG regional de 1995 NO es ninguno de los dos puntos que el IELIG nacional tiene hoy dentro del límite (GR005 y GR006), que llevan otro nombre y están dados de alta como POI aparte; Wikimedia Commons (foto: Aleuze, CC BY-SA 3.0)' WHERE slug = 'mirador-de-los-barrancos-de-gebas' AND park_id = (SELECT id FROM parks WHERE slug = 'barrancos-de-gebas');
